import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.PlayerFog{Stack: []string{"minecraft:fog_ocean", "minecraft:fog_hell"}}
TWO_FOGS = bytes.fromhex("02136d696e6563726166743a666f675f6f6365616e126d696e6563726166743a666f675f68656c6c")

# generated by gophertunnel b8bd735:
# &packet.PlayerFog{}
EMPTY = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.PlayerFogPacket(fog_stack=["minecraft:fog_ocean", "minecraft:fog_hell"]),
        TWO_FOGS,
        id="two-fogs",
    ),
    pytest.param(v2225.PlayerFogPacket(), EMPTY, id="empty-stack-is-a-lone-zero-count"),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_player_fog_is_packet_160(version):
    assert version.packets[160] is version.PlayerFogPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_fog_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_fog_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
